function getEntriesByDotNotation(object, searchKey) {
    const entries = [];

    // Check both properties and arrays for matching keys
    Object.keys(object).forEach(key => {
        const currentObj = object[key];
        const isEntryMatched = typeof currentObj === 'object' && currentObj !== null;

        if (isEntryMatched) {
            entries.push(currentObj);
        } else if (Array.isArray(currentObj)) {
            currentObj.forEach(entry => {
                const isArrayNestedObject = Array.isArray(entry);

                if (isArrayNestedObject) {
                    entries.push(...getEntriesByDotNotation(entry, searchKey));
                }
            });
        }
    });

    return entries;
}

